type Phase = 'investigation' | 'containment' | 'won' | 'lost'
type Modal = 'briefing' | 'reveal' | 'diagnosis' | 'advance' | 'complete' | 'event' | 'wrong' | 'win' | 'lost' | 'feedback' | null
type MissionAct = 'proteger' | 'investigar' | 'decidir' | 'controlar' | 'resultado'
type PilotStage = 'called' | 'field' | 'map' | 'board' | 'tactical' | 'response' | 'diagnosis' | 'result'
type Student = { name: string; semester: string; focus: string }
type Reveal = Clue | Intervention
type Area = 'investigacao' | 'conduta' | 'controle' | 'tempo' | 'diagnostico'
type Log = { id: string; area: Area; title: string; note: string; tone: 'good' | 'warn' | 'neutral' }
type Player = { playerId: string; xp: number; coins: number; completed: number[]; dailyClaimed: string; lastActiveDay: string; streak: number; bestScore: number; inventory: string[]; equippedStyle: string }
type RewardSummary = { xp: number; coins: number; missionXP: number; dailyXP: number; speedXP: number; firstClear: boolean }
type Participant = { displayName: string; xp: number; bestScore: number; plays: number; completed: number; createdAt: string; lastPlayedAt: string | null; lastMissionId: number | null }
type Records = { summary: { players: number; active_players: number; plays: number; completed: number }; leaderboards: { score: RecordEntry[]; xp: RecordEntry[]; plays: RecordEntry[] }; participants: Participant[] }
type RecordEntry = { displayName: string; value: number }
type AuthConfig = { googleEnabled: boolean; googleClientId: string | null; adminEnabled?: boolean }
type AuthStatus = { googleLinked: boolean; emailRecorded?: boolean }
type AdminData = { admin: string; overview: { visits: number; visits_24h: number; active_30d: number; players: number; google_links: number; runs: number }; players: { displayName: string; email: string | null; xp: number; coins: number; plays: number; bestScore: number; completed: number; createdAt: string; lastPlayedAt: string | null; lastMissionId: number | null; visits: number }[]; missions: { missionId: number; runs: number; wins: number; averageScore: number }[]; funnel: { missionId: number; starts: number; finishes: number; hintRuns: number; tacticalRuns: number; diagnosisRuns: number }[] }
type JourneyRun = { missionId: number; variantId: string | null; outcome: 'won' | 'lost'; score: number; xpEarned: number; coinsEarned: number; cycle: number; cases: number; care: number; riskUsed: boolean; competencies: Record<string, number>; createdAt: string }
