const routeChallengeFor = (missionId: number, variantId: string | null): RouteChallenge | undefined => {
  const variants = operationalVariants[missionId]
  return variants?.[1]?.id === variantId ? alternateRouteChallenges[missionId] : routeChallenges[missionId]
}
const shuffledRouteIds = (challenge: RouteChallenge | undefined): string[] => {
  const ids = challenge?.options.map((option) => option.id) || []
  for (let index = ids.length - 1; index > 0; index--) { const pick = Math.floor(Math.random() * (index + 1)); [ids[index], ids[pick]] = [ids[pick], ids[index]] }
  return ids
}

