const localDay = () => new Date().toLocaleDateString('en-CA', { timeZone: 'America/Sao_Paulo' })
const dayBefore = (day: string) => { const [year, month, date] = day.split('-').map(Number); return new Date(Date.UTC(year, month - 1, date - 1)).toISOString().slice(0, 10) }
const profileCodePattern = /^MISSAO-[A-HJ-NP-Z2-9]{4}-[A-HJ-NP-Z2-9]{4}-[A-HJ-NP-Z2-9]{4}$/
const identityVersionKey = 'missao-imunidade-identidade-v2'
const studentKey = 'missao-imunidade-estudante-v2'
const playerKey = 'missao-imunidade-jogador-v2'
const gameKey = 'missao-imunidade-partida-v2'
const codeAlphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'
const randomCodePart = () => Array.from(window.crypto.getRandomValues(new Uint8Array(4)), (value) => codeAlphabet[value & 31]).join('')
const generateProfileCode = () => `MISSAO-${randomCodePart()}-${randomCodePart()}-${randomCodePart()}`
const newPlayer = (playerId = generateProfileCode()): Player => ({ playerId, xp: 0, coins: 0, completed: [], dailyClaimed: '', lastActiveDay: '', streak: 0, bestScore: 0, inventory: ['central'], equippedStyle: 'central' })
const resetLegacyIdentity = () => { if (localStorage.getItem(identityVersionKey) === '2') return; ['missao-imunidade-estudante', 'missao-imunidade-jogador-v1', 'missao-imunidade-partida-v1', 'missao-imunidade-partida-v2'].forEach((key) => localStorage.removeItem(key)); localStorage.setItem(identityVersionKey, '2') }
const missionWithVariant = (base: Mission | null | undefined, variantId: string | null) => { if (!base || !variantId) return base; if (base.id === 2) { const variant = districtVariants.find((item) => item.id === variantId); if (!variant) return base; const { id: _id, label: _label, ...content } = variant; return { ...base, ...content } } const variant = operationalVariants[base.id]?.find((item) => item.id === variantId); return variant ? { ...base, openingSyndrome: variant.openingSyndrome, brief: variant.brief, initialData: variant.initialData } : base }

