const routeChoiceGlyphs: Record<number, [string, string, string]> = {
  9: ['◉', '◌', '✚'], 10: ['♧', '⌁', '◌'], 11: ['⌂', '◇', '✚'],
  12: ['⚑', '◌', '◇'], 13: ['▰', '≈', '◌'], 14: ['✚', '⌁', '⌂'],
}

function RouteChallengePanel({ missionId, challenge, routeColor, routeIcon, result, selectedId, onChoose }: { missionId: number; challenge: RouteChallenge | undefined; routeColor: string; routeIcon: string; result: Log | undefined; selectedId: string | undefined; onChoose: (choiceId: string) => void }) {
  if (!challenge) return null
  const glyphs = routeChoiceGlyphs[missionId] || ['◉', '◇', '✚']
  const glyphFor = (choiceId: string) => {
    const primaryIndex = routeChallenges[missionId]?.options.findIndex((option) => option.id === choiceId) ?? -1
    const alternateIndex = alternateRouteChallenges[missionId]?.options.findIndex((option) => option.id === choiceId) ?? -1
    return glyphs[primaryIndex >= 0 ? primaryIndex : alternateIndex] || '◇'
  }
  return <section className={`route-challenge route-${routeColor} ${result ? 'resolved' : ''}`} aria-labelledby="route-challenge-title">
    <header><span>DESAFIO DA ROTA · OPCIONAL</span><b>Boa prioridade: +1 recurso</b></header>
    <div className="route-challenge-heading"><span className="route-challenge-emblem" aria-hidden="true">{routeIcon}</span><div><h2 id="route-challenge-title">{challenge.title}</h2><p>{challenge.prompt}</p></div></div>
    <div className="route-challenge-options">{challenge.options.map((option, index) => <button type="button" className={`${selectedId === option.id ? 'selected' : ''} ${selectedId === option.id ? option.correct ? 'right' : 'review' : ''}`} disabled={Boolean(result)} onClick={() => onChoose(option.id)} key={option.id}>
      <span className="route-choice-art" aria-hidden="true"><span>{glyphFor(option.id)}</span><small>{String(index + 1).padStart(2, '0')}</small></span><span className="route-choice-copy">{option.label}</span>
    </button>)}</div>
    {result && <aside className={result.tone === 'good' ? 'right' : 'review'} role="status"><b>{result.tone === 'good' ? 'Boa leitura da rota' : 'Um ponto para revisar no debriefing'}</b><p>{result.note}</p><small>{result.tone === 'good' ? 'Bônus simulado aplicado: +1 recurso para investigar.' : 'A exploração continua normalmente. A equipe registrou esta decisão para a revisão final.'}</small></aside>}
    <small className="route-challenge-footnote">Este exercício é uma simulação educativa e não bloqueia a investigação.</small>
  </section>
}

function RouteMapEffect({ result }: { result: Log | undefined }) {
  if (!result) return null
  const protectedRoute = result.tone === 'good'
  return <aside className={`route-map-effect ${protectedRoute ? 'protected' : 'review'}`} aria-live="polite">
    <span className="route-map-effect-icon" aria-hidden="true">{protectedRoute ? '✦' : '↗'}</span>
    <span><small>{protectedRoute ? 'FRENTE REFORÇADA' : 'ROTA EM REVISÃO'}</small><b>{protectedRoute ? 'A equipe ganhou capacidade de investigar.' : 'A investigação segue aberta.'}</b></span>
  </aside>
}

function FieldPulse({ mission, stage, cases, clues }: { mission: Mission; stage: PilotStage; cases: number; clues: number }) { const lines = pulseLines[mission.id] || []; const index = Math.min(lines.length - 1, stage === 'called' ? 0 : clues ? Math.min(clues, lines.length - 1) : 1); return <aside className="field-pulse" aria-live="polite"><span><i /> SINAL DA CENTRAL</span><b>{lines[index]}</b><small>{cases} casos acompanhados · {clues} pista{clues === 1 ? '' : 's'} reunida{clues === 1 ? '' : 's'}</small></aside> }

function HintDock({ stage, energy, used, clues, onUse }: { stage: PilotStage; energy: number; used: string[]; clues: number; onUse: (kind: 'orientacao' | 'pista') => void }) { const orientKey = `${stage}-orientacao`; const clueKey = `${stage}-pista`; const orientation = stage === 'map' ? 'Comece pela pergunta que protege alguém agora ou que separa melhor os diferenciais.' : stage === 'board' ? 'Olhe para as categorias: duas lentes diferentes valem mais que repetir a mesma fonte.' : 'Leia o que muda uma decisão imediata antes de procurar confirmação.'; const focused = clues < 3 ? 'Ainda não é hora de nomear a doença: busque uma pista de outro papel da equipe.' : 'A resposta inicial pode ser proporcional ao risco mesmo antes do fechamento diagnóstico.'; return <section className="hint-dock"><div><span>⚡ ENERGIA DA CENTRAL</span><b>{Array.from({ length: 4 }, (_, index) => <i className={index < energy ? 'filled' : ''} key={index}>✦</i>)}</b><small>Dicas orientam; elas não revelam o diagnóstico.</small></div><div className="hint-actions"><button disabled={energy < 1 || used.includes(orientKey)} onClick={() => onUse('orientacao')}><b>Orientação · 1</b><span>{used.includes(orientKey) ? orientation : 'Mostrar direção segura'}</span></button><button disabled={energy < 2 || used.includes(clueKey)} onClick={() => onUse('pista')}><b>Foco investigativo · 2</b><span>{used.includes(clueKey) ? focused : 'Mostrar o que ainda falta'}</span></button></div></section> }

function RouteChallengeReview({ challenge, selectedId }: { challenge: RouteChallenge | undefined; selectedId: string | undefined }) {
  if (!challenge || !selectedId) return null
  const selected = challenge.options.find((option) => option.id === selectedId)
  if (!selected) return null
  return <details className="route-review">
    <summary><span>REVISÃO DA ROTA</span><b>{challenge.title}</b><small>{selected.correct ? 'Sua equipe priorizou bem. Compare os outros caminhos.' : 'Veja onde a decisão perdeu força e qual caminho protegeria melhor.'}</small></summary>
    <div className="route-review-options">{challenge.options.map((option) => <article className={`${option.correct ? 'recommended' : 'alternative'} ${option.id === selectedId ? 'chosen' : ''}`} key={option.id}>
      <span>{option.id === selectedId ? 'SUA ESCOLHA' : option.correct ? 'MELHOR PRIORIDADE' : 'OUTRA POSSIBILIDADE'}</span>
      <b>{option.label}</b><p>{option.feedback}</p>
    </article>)}</div>
  </details>
}

function DecisionReport({ logs }: { logs: Log[] }) {
  const entries = logs.filter((entry) => entry.area === 'conduta' || entry.area === 'controle' || entry.area === 'diagnostico' || entry.id.startsWith('route-challenge-'))
  const protectedMoves = entries.filter((entry) => entry.tone === 'good')
  const fragileMoves = entries.filter((entry) => entry.tone === 'warn')
  const outcome = fragileMoves.length ? 'Resposta com lacunas' : protectedMoves.length >= 3 ? 'Território mais protegido' : 'Resposta em consolidação'
  const strength = protectedMoves.find((entry) => entry.area === 'conduta') || protectedMoves[0]
  const review = fragileMoves.find((entry) => entry.area === 'diagnostico') || fragileMoves[0]
  const nextStep = review ? 'Retome a pista que separa os diferenciais antes de fechar a hipótese.' : protectedMoves.some((entry) => entry.area === 'diagnostico') ? 'Você conectou as evidências. No próximo caso, tente preservar essa mesma ordem de raciocínio.' : 'Cruze mais de uma lente antes de transformar uma impressão inicial em conclusão.'
  return <section className="decision-report"><span>DEBRIEFING DA SUA EQUIPE</span><h2>Como esta partida se desenrolou</h2><div className={`consequence-meter ${fragileMoves.length ? 'fragile' : protectedMoves.length >= 3 ? 'strong' : ''}`}><div><b>{outcome}</b><small>{protectedMoves.length} {protectedMoves.length === 1 ? 'ação protetora' : 'ações protetoras'} · {fragileMoves.length} {fragileMoves.length === 1 ? 'escolha frágil' : 'escolhas frágeis'}</small></div><span><i style={{ width: `${Math.max(12, Math.min(100, protectedMoves.length * 26 - fragileMoves.length * 18 + 30))}%` }} /></span></div><div className="personal-debrief"><article className="debrief-strength"><span>O QUE SUA EQUIPE FEZ BEM</span><b>{strength ? strength.title : 'Você manteve a investigação em movimento.'}</b><p>{strength ? strength.note : 'Continue registrando pistas de fontes diferentes para fortalecer a conclusão.'}</p></article><article className="debrief-next"><span>PRÓXIMO GANHO DE DOMÍNIO</span><b>{review ? review.title : 'Conectar as lentes antes do fechamento'}</b><p>{review ? review.note : nextStep}</p></article></div><ol className="debrief-timeline">{entries.map((entry, index) => <li className={entry.tone} key={entry.id}><i>{index + 1}</i><div><b>{entry.title}</b><p>{entry.note}</p></div></li>)}</ol></section>
}

const diagnosticLens: Record<number, string> = {
  1: 'a combinação entre perda rápida de líquidos e vínculo com água potencialmente contaminada',
  2: 'o padrão clínico dominante da variação e a exposição a Aedes',
  3: 'o pródromo respiratório, o exantema e a rede de contatos em espaço compartilhado',
  4: 'a evolução prolongada, o ambiente compartilhado e a investigação respiratória adequada',
  5: 'o padrão de transmissão dentro da unidade e a identificação laboratorial dirigida',
  6: 'febre com calafrios, exposição em área de transmissão e confirmação parasitológica',
  7: 'a síndrome meníngea aguda e os contatos próximos com exposição relevante',
  8: 'icterícia com exposição alimentar ou hídrica comum e confirmação específica',
  9: 'a evolução bifásica com icterícia e sangramento após exposição em área de risco',
  10: 'a tosse paroxística e a exposição de um lactente a contatos sintomáticos',
  11: 'a integração entre exposição, fase aguda, sinal de Romaña e confirmação apropriada',
  12: 'a categoria da exposição, o cuidado imediato da ferida e a resposta antes dos sintomas',
  13: 'o contato com água ou lama após enchente e os sinais de comprometimento renal, hepático ou pulmonar',
  14: 'trismo e espasmos após ferimento contaminado, sem transmissão entre pessoas',
}

function DifferentialReview({ mission }: { mission: Mission }) { const lens = diagnosticLens[mission.id] || 'a evidência mais discriminativa do dossiê'; return <details className="differential-review"><summary>Por que cada alternativa foi adequada ou não?</summary><p>O diagnóstico correto é <b>{mission.disease}</b>. Esta revisão aparece somente depois do encerramento.</p><div>{mission.diagnoses.map((diagnosis) => <article className={diagnosis === mission.disease ? 'correct' : ''} key={diagnosis}><b>{diagnosis === mission.disease ? '✓' : '↗'} {diagnosis}</b><span>{diagnosis === mission.disease ? `Explica melhor ${lens}.` : `${diagnosis} pode compartilhar achados iniciais, mas não coloca ${lens} no centro do caso.`}</span></article>)}</div><p className="discriminative-note"><b>Dado de maior peso:</b> {mission.diagnosticCheck.options.find((item) => item.id === mission.diagnosticCheck.correctId)?.label}</p></details> }

function PlayerHud({ player, compact = false }: { player: Player; compact?: boolean }) { const level = Math.floor(player.xp / 700) + 1; const progress = player.xp % 700; const cosmetic = cosmeticById[player.equippedStyle] || cosmeticById.central; return <div className={`player-hud ${compact ? 'compact' : ''}`} aria-label={`Nível ${level}, ${player.xp} XP e ${player.coins} moedas`}><div className={`player-avatar avatar-${cosmetic.tone}`} title={cosmetic.label}>{cosmetic.icon}<span>{level}</span></div><div className="player-level"><small>NÍVEL {level} · {levelTitle(level)}</small><div><i style={{ width: `${Math.max(5, progress / 7)}%` }} /></div><b>{progress}/700 XP</b></div><div className="player-coins">◉ <b>{player.coins}</b></div></div> }

function Map({ mission, inContainment }: { mission: Mission; inContainment: boolean }) { return <div className="map-panel panel"><div className="panel-heading"><div><span className="eyebrow">{mission.caseCode.toUpperCase()} · AGENTE NÃO REVELADO</span><h1>Foco do <em>caso</em></h1></div><span className="live">● AO VIVO</span></div><div className="world-map"><img src={worldMapImage} alt="Mapa-múndi ilustrativo" /><div className={`focus-line ${inContainment ? 'contained' : ''}`} style={{ left: `${mission.mapPosition.x}%`, top: `${mission.mapPosition.y}%` }} /><div className={`outbreak-pin ${inContainment ? 'contained' : ''}`} style={{ left: `${mission.mapPosition.x}%`, top: `${mission.mapPosition.y}%` }}><span className="pin-ring" /><span className="pin-core" /><div className="pin-label"><b>{inContainment ? 'RESPOSTA ATIVA' : 'FOCO EM ANÁLISE'}</b><br />{mission.location}</div></div><div className="map-scan" /></div><div className="map-footer"><span>{mission.region} · {mission.location}</span></div></div> }

function MissionScene({ urgentCare, pendingLab, act }: { urgentCare: boolean; pendingLab: boolean; act: MissionAct }) {
  const voice = pendingLab ? { image: andrePortrait, name: 'Dr. André', text: 'A amostra está a caminho do laboratório. Use o ciclo para cruzar cuidado, exposição e vigilância.' } : act === 'proteger' ? { image: helenaPortrait, name: 'Dra. Helena', text: 'A enchente trouxe pacientes desidratados. Acione o cuidado imediato antes de procurar a resposta.' } : act === 'investigar' ? { image: camilaPortrait, name: 'Dra. Camila', text: 'Agora escolha uma lente. Cada personagem revela uma parte diferente do mapa do surto.' } : act === 'decidir' ? { image: rafaelPortrait, name: 'Dr. Rafael', text: 'As pistas já conversam entre si. Junte o padrão clínico e a exposição antes de defender sua hipótese.' } : urgentCare ? { image: helenaPortrait, name: 'Dra. Helena', text: 'O ponto de reidratação está ativo. Agora transforme a hipótese em medidas de controle.' } : { image: helenaPortrait, name: 'Central', text: 'A equipe está pronta para o próximo passo.' }
  return <section className="mission-scene mahan-scene panel" aria-label="Central de comando de Porto de Mahan"><div className="scene-mahan-art" style={{ backgroundImage: `url(${mahanOperation})` }} /><div className="scene-grid" /><div className="scene-header"><span>OPERAÇÃO MARÉ SEGURA</span><b>PORTO DE MAHAN</b></div><div className="scene-portraits"><img src={helenaPortrait} alt="Dra. Helena Rocha" /><img src={rafaelPortrait} alt="Dr. Rafael Nunes" /><img src={camilaPortrait} alt="Dra. Camila Torres" /><img src={andrePortrait} alt="Dr. André Lima" /></div><div className="scene-dialogue"><div className="scene-avatar"><img src={voice.image} alt="" /></div><p><b>{voice.name}:</b> {voice.text}</p></div><div className="scene-objective"><span>OBJETIVO</span><b>Proteger vidas e interromper a exposição.</b></div></section>
}

function OperationScene({ mission, urgentCare, pendingLab, act }: { mission: Mission; urgentCare: boolean; pendingLab: boolean; act: MissionAct }) {
  const sceneIndex = Math.max(0, mission.id - 2)
  const labels = ['OPERAÇÃO VETOR EM ALERTA', 'OPERAÇÃO REDE PROTEGIDA', 'OPERAÇÃO AR SEGURO', 'OPERAÇÃO BARREIRA ATIVA']
  const voice = pendingLab ? { image: andrePortrait, name: 'Dr. André', text: 'O exame está em processamento. Use este ciclo para cruzar clínica, território e vigilância.' } : act === 'proteger' ? { image: helenaPortrait, name: 'Dra. Helena', text: `${mission.priorityAction.title}. Esta é a primeira ordem da central.` } : act === 'investigar' ? { image: camilaPortrait, name: 'Dra. Camila', text: 'Escolha um personagem. Toda pista nova reduz uma dúvida diferente.' } : act === 'decidir' ? { image: rafaelPortrait, name: 'Dr. Rafael', text: 'Chegou a hora de conectar as pistas e defender a hipótese mais forte.' } : urgentCare ? { image: helenaPortrait, name: 'Dra. Helena', text: 'A proteção inicial está ativa. Agora escolha medidas para reduzir novas exposições.' } : { image: helenaPortrait, name: 'Central', text: 'A equipe aguarda a próxima ordem.' }
  return <section className={`mission-scene operation-scene scene-${sceneIndex} panel`} aria-label={`Central de comando de ${mission.shortName}`}><div className="scene-grid" /><div className="operation-scene-art" style={{ backgroundImage: `url(${operationScenes})` }} /><div className="scene-header"><span>{labels[sceneIndex]}</span><b>{mission.shortName.toUpperCase()}</b></div><div className="operation-alert"><span>⚡ AGORA</span><b>{act === 'proteger' ? mission.priorityAction.action : act === 'investigar' ? 'Escolha uma lente' : act === 'decidir' ? 'Defenda a hipótese' : 'Aplique a resposta'}</b></div><div className="scene-portraits operation-portraits"><img src={helenaPortrait} alt="Dra. Helena Rocha" /><img src={rafaelPortrait} alt="Dr. Rafael Nunes" /><img src={camilaPortrait} alt="Dra. Camila Torres" /><img src={andrePortrait} alt="Dr. André Lima" /></div><div className="scene-dialogue"><div className="scene-avatar"><img src={voice.image} alt="" /></div><p><b>{voice.name}:</b> {voice.text}</p></div><div className="scene-objective"><span>OBJETIVO</span><b>{mission.priorityAction.text}</b></div></section>
}

function Board({ mission, clues, interventions, inContainment, finished, labConfirmed, requiredComplete, total, logs }: { mission: Mission; clues: Clue[]; interventions: Intervention[]; inContainment: boolean; finished: boolean; labConfirmed: boolean; requiredComplete: boolean; total: number; logs: Log[] }) { const guidance = finished ? 'Caso encerrado. Abra o debriefing para revisar suas decisões.' : clues.length === 0 ? 'Escolha uma frente para registrar o primeiro achado.' : clues.length < 3 ? 'Cruze esta descoberta com outra lente antes de concluir.' : clues.length < 6 ? 'Você já pode defender uma hipótese; investigue mais se ainda houver dúvida.' : 'Seu dossiê está robusto. Pese as evidências.'; return <aside className="intel-panel panel evidence-board"><div className="intel-heading"><div><span className="eyebrow">QUADRO DO CASO</span><h2>{finished ? 'Caso encerrado' : inContainment ? 'Resposta em andamento' : 'Evidências reunidas'}</h2></div><span>{finished ? '✓' : inContainment ? `${interventions.length}/4` : `${clues.length}/${total}`}</span></div>{!inContainment && <div className="lens-progress">{team.map((member) => { const count = clues.filter((item) => item.role === member.role).length; return <div key={member.role} className={count ? `active ${member.tone}` : ''}><span>{member.icon}</span><b>{count}/2</b><small>{member.specialty.replace('Medicina de ', '')}</small></div> })}</div>}<div className="evidence-list">{!inContainment && !clues.length && <div className="empty-state"><span>⌁</span><p>{guidance}</p></div>}{!inContainment && clues.map((clue) => <article className="evidence-card" key={clue.id}><span>{clue.category} · camada {clue.level}</span><h3>{clue.title}</h3><p>{clue.text}</p></article>)}{inContainment && <div className="response-status"><div className="agent-confirmed">✓ <span>{labConfirmed ? 'AGENTE CONFIRMADO' : 'HIPÓTESE ORIENTADORA'}</span><b>{mission.disease}</b></div><p>Para concluir, aplique três medidas e inclua as duas prioritárias.</p>{interventions.map((item) => <article className="evidence-card response-card" key={item.id}><span>{item.label}</span><h3>{item.title}</h3><p>{item.text}</p></article>)}</div>}</div>{logs.length > 0 && <div className="decision-feed"><span>ÚLTIMA DECISÃO</span><b>{logs[logs.length - 1].title}</b></div>}<div className="hypothesis"><span>{finished ? 'PRÓXIMO PASSO' : inContainment ? 'OBJETIVO' : 'PRÓXIMO PASSO'}</span><b>{finished ? 'Abra o debriefing para revisar a partida.' : inContainment ? (requiredComplete ? 'Prioridades aplicadas' : 'Priorize as medidas indicadas') : guidance}</b></div></aside> }

function Competencies({ logs, score }: { logs: Log[]; score: number }) { const has = (area: Area, tone?: Log['tone']) => logs.some((log) => log.area === area && (!tone || log.tone === tone)); const investigations = logs.filter((log) => log.area === 'investigacao').length; const entries = [['Raciocínio / diagnóstico', has('diagnostico', 'good') ? 'consistente' : 'em desenvolvimento', has('diagnostico', 'good') ? 'Sua defesa conectou hipóteses e evidências.' : 'Revise qual dado realmente separa os diferenciais.'], ['Investigação', investigations >= 2 ? 'consistente' : 'em desenvolvimento', investigations >= 2 ? `Você cruzou ${investigations} frentes de investigação antes de concluir.` : 'Cruze ao menos duas lentes antes de concluir.'], ['Conduta / tratamento', has('conduta', 'good') ? 'consistente' : 'atenção', has('conduta', 'good') ? 'Você protegeu pacientes enquanto investigava.' : 'Reavalie as prioridades de cuidado precoce.'], ['Controle / prevenção', has('controle', 'good') ? 'consistente' : 'em desenvolvimento', has('controle', 'good') ? 'Você aplicou uma medida prioritária no cenário.' : 'Conecte a resposta à forma de transmissão.'], ['Tempo de resposta', has('tempo', 'warn') ? 'atenção' : 'consistente', has('tempo', 'warn') ? 'A capacidade operacional ficou curta em um momento da partida.' : 'Você administrou ações e ciclos sem perda operacional registrada.']]; return <div className="competencies"><div className="score"><span>RESULTADO DA PARTIDA</span><b>{score} pts</b></div><span className="eyebrow">SEU DESEMPENHO POR ÁREA</span>{entries.map(([title, status, note]) => <article key={title}><div><b>{title}</b><span className={`competency-${status === 'consistente' ? 'good' : status === 'atenção' ? 'warn' : 'neutral'}`}>{status}</span></div><p>{note}</p></article>)}</div> }

function MissionSteps({ act }: { act: MissionAct }) {
  const steps = [{ id: 'proteger', icon: '🛟', label: '1. Proteja' }, { id: 'investigar', icon: '🔎', label: '2. Investigue' }, { id: 'decidir', icon: '🧩', label: '3. Decida' }, { id: 'controlar', icon: '🛡️', label: '4. Controle' }]
  const copy = act === 'proteger' ? ['Primeiro: proteja as pessoas', 'Use o cartão dourado da central. Depois a equipe entra em ação.'] : act === 'investigar' ? ['Agora: escolha um personagem', 'Cada pessoa traz uma peça diferente do quebra-cabeça.'] : act === 'decidir' ? ['Agora: conecte as pistas', 'Você já pode defender uma hipótese ou buscar mais uma evidência.'] : act === 'controlar' ? ['Agora: reduza o surto', 'Aplique três medidas, incluindo as duas prioritárias.'] : ['Missão concluída', 'Abra o debriefing para revisar suas escolhas.']
  return <section className={`mission-steps act-${act}`} aria-label={`Etapa atual: ${copy[0]}`}><div className="step-track">{steps.map((step) => <div key={step.id} className={`step-dot ${step.id === act ? 'active' : steps.findIndex((item) => item.id === step.id) < steps.findIndex((item) => item.id === act) ? 'done' : ''}`}><span>{step.icon}</span><b>{step.label}</b></div>)}</div><div className="act-callout"><div><span>PASSO A PASSO</span><b>{copy[0]}</b><p>{copy[1]}</p></div></div></section>
}

function GameGuide({ phase, urgentCare, clueCount, onDismiss }: { phase: Phase; urgentCare: boolean; clueCount: number; onDismiss: () => void }) {
  const step = !urgentCare
    ? { target: 'care-priority', title: 'Primeira prioridade', text: 'O cenário pede uma ação de proteção antes da confirmação. Acione a prioridade da central.', action: 'Mostrar prioridade' }
    : phase === 'investigation' && clueCount < 3
      ? { target: 'team-missions', title: 'Monte o quebra-cabeça', text: 'Agora escolha uma missão da equipe. Cada personagem entrega uma peça diferente do caso.', action: 'Ver missões' }
      : phase === 'investigation'
        ? { target: 'diagnosis-action', title: 'Hora de defender', text: 'Você já reuniu pistas suficientes. Conecte-as e apresente sua hipótese.', action: 'Defender hipótese' }
        : { target: 'response-actions', title: 'Controle o surto', text: 'Escolha medidas prioritárias para reduzir os casos e fechar a missão.', action: 'Ver medidas' }
  return <aside className={`game-guide game-guide-${step.target}`} aria-live="polite"><img src={ninaAssistant} alt="Nina, assistente da central" /><div className="game-guide-bubble"><button className="guide-close" onClick={onDismiss} aria-label="Fechar orientação da Nina">×</button><span>NINA · GUIA DA MISSÃO</span><h2>{step.title}</h2><p>{step.text}</p><b className="guide-arrow">↓</b></div></aside>
}

function Dialogs({ modal, mission, cycle, actions, cases, baseProjected, projected, event, eventOption, eventOptions, clues, diagnosis, rationale, diagnoses, rationaleOptions, error, reveal, outcome, score, reward, logs, onClose, onCloseReveal, onSelectDiagnosis, onSelectRationale, onConfirm, onShowEvent, onSelectEventOption, onAdvance, onFeedback, onReset, onCampaign }: { modal: Modal; mission: Mission; cycle: number; actions: number; cases: number; baseProjected: number; projected: number; event: CycleEvent; eventOption: CycleEvent['options'][number] | null; eventOptions: CycleEvent['options']; clues: number; diagnosis: string; rationale: string; diagnoses: string[]; rationaleOptions: Mission['diagnosticCheck']['options']; error: string; reveal: Reveal | null; outcome: string; score: number; reward: number; logs: Log[]; onClose: () => void; onCloseReveal: () => void; onSelectDiagnosis: (value: string) => void; onSelectRationale: (value: string) => void; onConfirm: () => void; onShowEvent: () => void; onSelectEventOption: (value: CycleEvent['options'][number]) => void; onAdvance: () => void; onFeedback: () => void; onReset: () => void; onCampaign: () => void }) {
  if (!modal) return null; const isClue = reveal && 'category' in reveal
  return <div className="modal-backdrop" role="presentation"><section className={`modal ${modal === 'briefing' ? 'briefing-modal' : ''} ${modal === 'diagnosis' ? 'diagnosis-modal' : ''} ${modal === 'reveal' ? 'reveal-modal' : ''} ${modal === 'win' || modal === 'lost' ? 'debrief-modal' : ''}`} role="dialog" aria-modal="true">
    {modal === 'briefing' && <><span className="modal-kicker">{mission.caseCode.toUpperCase()} · AGENTE OCULTO</span><div className="briefing-icon">⌁</div><h2>{mission.shortName}</h2><p>{mission.id === 1 ? 'Você coordena a central. Primeiro proteja, depois investigue e, por fim, defenda a hipótese.' : 'Cada ciclo tem três decisões. Escolha uma lente, leia o achado e monte o quadro de evidências antes de defender sua hipótese.'}</p><div className="briefing-case"><b>{mission.openingSyndrome}</b><p>{mission.brief}</p></div><div className="briefing-facts">{mission.initialData.map((item) => <span key={item.label}>{item.label}<b>{item.value}</b></span>)}</div><div className="modal-actions"><button className="primary" onClick={onClose}>Assumir caso</button></div></>}
    {modal === 'reveal' && reveal && <><span className="modal-kicker">{isClue ? `NOVA EVIDÊNCIA · ${(reveal as Clue).category.toUpperCase()}` : 'AÇÃO REGISTRADA'}</span><div className="reveal-symbol">{isClue ? '⌁' : '✓'}</div><h2>{reveal.title}</h2><p className="reveal-text">{reveal.text}</p>{!isClue && (reveal as Intervention).teachingNote && <div className="teaching-note"><span>POR QUE ESTA DECISÃO IMPORTA</span><p>{(reveal as Intervention).teachingNote}</p></div>}<div className="reveal-foot"><span>{actions} {actions === 1 ? 'decisão restante neste ciclo' : 'decisões restantes neste ciclo'}</span><b>{isClue ? 'Adicionado ao Quadro do caso' : 'Situação atualizada'}</b></div><div className="modal-actions"><button className="primary" onClick={onCloseReveal}>{actions === 0 ? 'Ver fechamento do ciclo' : 'Continuar'}</button></div></>}
    {modal === 'diagnosis' && <><span className="modal-kicker">DEFESA DE HIPÓTESE · {clues} EVIDÊNCIAS</span><h2>Qual hipótese explica melhor o conjunto?</h2><p>Escolha um diferencial e o dado com maior poder de separá-lo. Uma defesa precisa cruzar pelo menos duas lentes de investigação.</p><div className="diagnoses">{diagnoses.map((item) => <button className={diagnosis === item ? 'selected' : ''} onClick={() => onSelectDiagnosis(item)} key={item}>{item}</button>)}</div><div className="rationale"><span>{mission.diagnosticCheck.question}</span>{rationaleOptions.map((item) => <button key={item.id} className={rationale === item.id ? 'selected' : ''} onClick={() => onSelectRationale(item.id)}>{item.label}</button>)}</div><div className="modal-actions"><button className="secondary" onClick={onClose}>Voltar ao quadro</button><button className="primary" disabled={!diagnosis || !rationale} onClick={onConfirm}>Defender hipótese</button></div></>}
    {(modal === 'advance' || modal === 'complete') && <><span className="modal-kicker">{modal === 'complete' ? `CICLO ${cycle} CONCLUÍDO` : `FECHAR CICLO ${cycle}`}</span><h2>{modal === 'complete' ? 'Hora de observar a evolução do cenário.' : 'Abrir mão de decisões restantes?'}</h2><p>{modal === 'complete' ? 'As três decisões foram usadas. O próximo ciclo traz um sinal operacional para sua equipe.' : `Você ainda tem ${actions} decisão${actions > 1 ? 'ões' : ''}. Fechar agora reduz seu tempo de investigação.`}</p><div className="projection"><span>Casos ativos projetados</span><b>{cases} → {baseProjected}</b></div><div className="modal-actions">{modal === 'advance' && <button className="secondary" onClick={onClose}>Voltar às decisões</button>}<button className="primary" onClick={onShowEvent}>Ver situação do próximo ciclo</button></div></>}
    {modal === 'event' && <><span className="modal-kicker danger-text">SINAL OPERACIONAL · CICLO {cycle + 1}</span><div className="reveal-symbol event-symbol">!</div><h2>{event.title}</h2><p className="reveal-text">{event.text}</p><div className="event-options">{eventOptions.map((option) => <button className={eventOption?.id === option.id ? 'selected' : ''} onClick={() => onSelectEventOption(option)} key={option.id}><b>{option.label}</b><span>{option.text}</span><small>Impacto previsto: +{Math.round((option.pressureFactor - 1) * 100)}% nos casos ativos</small></button>)}</div>{eventOption && <><div className="teaching-note"><span>LEITURA DA ESCOLHA</span><p>{eventOption.teachingNote}</p></div><div className="projection"><span>Casos ativos no próximo ciclo</span><b>{cases} → {projected}</b></div></>}<div className="modal-actions"><button className="primary" disabled={!eventOption} onClick={onAdvance}>Iniciar ciclo {cycle + 1}</button></div></>}
    {modal === 'wrong' && <><span className="modal-kicker danger-text">DEFESA AINDA NÃO SUSTENTADA</span><h2>O caso avançou para o ciclo {cycle}.</h2><p>{error}</p><div className="modal-actions single"><button className="primary" onClick={onClose}>Voltar ao caso</button></div></>}
    {(modal === 'win' || modal === 'lost') && <><div className="trophy">{modal === 'win' ? '🏆' : '⚠️'}</div><span className={`modal-kicker ${modal === 'win' ? 'success-text' : 'danger-text'}`}>{modal === 'win' ? 'RESPOSTA CONCLUÍDA' : 'LIMITE CRÍTICO ATINGIDO'}</span><h2>{modal === 'win' ? `Debriefing: ${mission.disease}` : 'O caso exige uma nova tentativa'}</h2><p>{modal === 'win' ? mission.debrief : 'A pressão do cenário ultrapassou o limite antes de uma resposta adequada. Refaça o caso e compare suas decisões com o debriefing educativo.'}</p>{modal === 'win' && reward > 0 && <div className="reward-card"><span>RECOMPENSA DE PRIMEIRA CONCLUSÃO</span><b>+{reward} XP</b><small>+25 moedas para sua central</small></div>}{modal === 'win' && <Competencies logs={logs} score={score} />}<div className="learning-box"><span>APRENDIZADOS-CHAVE</span><ul>{mission.learningPoints.map((item) => <li key={item}>{item}</li>)}</ul><a href={mission.source.url} target="_blank" rel="noreferrer">{mission.source.label} ↗</a></div><div className="modal-actions result-actions"><button className="secondary" onClick={onFeedback}>Registrar opinião</button><button className="secondary" onClick={onCampaign}>Central de casos</button><button className="primary" onClick={onReset}>{modal === 'win' ? 'Reabrir caso' : 'Tentar novamente'}</button></div></>}
    {modal === 'feedback' && <FeedbackForm mission={mission} cycle={cycle} outcome={outcome} onClose={onClose} />}
  </section></div>
}

function FeedbackForm({ mission, cycle, outcome, onClose }: { mission: Mission; cycle: number; outcome: string; onClose: () => void }) { const [clarity, setClarity] = useState(0); const [engagement, setEngagement] = useState(0); const [reading, setReading] = useState(0); const [comment, setComment] = useState(''); const [saved, setSaved] = useState(false); const [copyState, setCopyState] = useState(''); const save = async () => { if (!clarity || !engagement || !reading) return; const entry = { mission: mission.caseCode, outcome, cycle, clarity, engagement, reading, comment: comment.trim(), createdAt: new Date().toISOString() }; try { const existing = JSON.parse(localStorage.getItem('missao-imunidade-feedback-v1') || '[]'); localStorage.setItem('missao-imunidade-feedback-v1', JSON.stringify([...existing, entry])); setSaved(true); try { await navigator.clipboard?.writeText(`Missão Imunidade — ${mission.caseCode}\nResultado: ${outcome}; ciclo: ${cycle}\nClareza: ${clarity}/5; decisões: ${engagement}/5; leitura: ${reading}/5\nComentário: ${entry.comment || '(sem comentário)'}`); setCopyState('Resumo copiado para compartilhar com a equipe.') } catch { setCopyState('Opinião salva neste navegador; a cópia automática não ficou disponível.') } } catch { setCopyState('Não foi possível salvar a opinião neste navegador.') } }; const scale = (label: string, value: number, setValue: (value: number) => void) => <div className="feedback-scale"><span>{label}</span><div>{[1, 2, 3, 4, 5].map((item) => <button type="button" aria-label={`${label}: ${item} de 5`} className={value === item ? 'selected' : ''} onClick={() => setValue(item)} key={item}>{item}</button>)}</div><small>1 = muito ruim · 5 = muito bom</small></div>; return <><span className="modal-kicker">TESTE DE EXPERIÊNCIA · OPINIÃO LOCAL</span><h2>Como foi este dossiê?</h2><p>Sua opinião fica somente neste navegador. Você decide se deseja compartilhar o resumo com a equipe.</p><div className="feedback-form">{scale('Entendi o ciclo e as consequências?', clarity, setClarity)}{scale('As escolhas pareceram significativas?', engagement, setEngagement)}{scale('A leitura e o celular ficaram confortáveis?', reading, setReading)}<label>O que confundiu, funcionou ou deveria mudar?<textarea value={comment} onChange={(event) => setComment(event.target.value)} maxLength={700} placeholder="Conte um momento específico do jogo." /></label></div>{(saved || copyState) && <p className="feedback-saved">{copyState || 'Opinião salva neste navegador.'}</p>}<div className="modal-actions"><button className="secondary" onClick={onClose}>Fechar</button><button className="primary" disabled={!clarity || !engagement || !reading || saved} onClick={save}>{saved ? 'Opinião registrada' : 'Salvar opinião'}</button></div></> }

function GoogleSignIn({ config, linked, emailRecorded, onSignIn }: { config: AuthConfig; linked: boolean; emailRecorded: boolean; onSignIn: (credential: string) => Promise<void> }) {
  const mount = useRef<HTMLDivElement>(null)
  const [message, setMessage] = useState('')
  const [consent, setConsent] = useState(false)
  useEffect(() => {
    if (!config.googleEnabled || !config.googleClientId || !mount.current || !consent) return
    const clientId = config.googleClientId
    let cancelled = false
    const render = () => {
      if (cancelled || !mount.current || !window.google) return
      window.google.accounts.id.initialize({ client_id: clientId, callback: (result) => { if (!result.credential) return; setMessage('Conectando sua jornada…'); void onSignIn(result.credential).then(() => setMessage('Jornada conectada.')).catch((error: unknown) => setMessage(error instanceof Error ? error.message : 'Não foi possível conectar sua jornada.')) } })
      window.google.accounts.id.renderButton(mount.current, { theme: 'outline', size: 'large', width: 290, text: 'continue_with', shape: 'pill', locale: 'pt-BR' })
    }
    const existing = document.querySelector<HTMLScriptElement>('script[data-missao-google]')
    if (existing) { if (window.google) render(); else existing.addEventListener('load', render, { once: true }); return () => { cancelled = true } }
    const script = document.createElement('script'); script.src = 'https://accounts.google.com/gsi/client'; script.async = true; script.defer = true; script.dataset.missaoGoogle = 'true'; script.addEventListener('load', render, { once: true }); document.head.appendChild(script)
    return () => { cancelled = true }
  }, [config.googleEnabled, config.googleClientId, onSignIn, consent])
  if (!config.googleEnabled) return null
  if (linked && emailRecorded) return <div className="google-signin google-linked-state" role="status"><strong>✓ Google vinculado</strong><p>Sua jornada está conectada à sua conta Google. Não é necessário entrar novamente.</p></div>
  return <div className="google-signin"><div><span />{linked ? 'atualize a autorização do vínculo' : 'ou conecte sua jornada ao Google'}<span /></div>{linked && <p>Seu vínculo foi criado antes do novo aviso de privacidade. Confirme novamente para manter o e-mail disponível somente ao administrador.</p>}<label className="google-consent"><input type="checkbox" checked={consent} onChange={(event) => setConsent(event.target.checked)} /><span>Concordo em vincular meu e-mail à jornada. Ele ficará visível somente no painel administrativo para controle de acesso e poderá ser removido mediante solicitação.</span></label>{consent ? <section ref={mount} aria-label="Entrar com Google" /> : <small>Marque a autorização para liberar o botão do Google.</small>}{message && <small aria-live="polite">{message}</small>}<p>O jogo não armazena sua senha, foto ou token do Google.</p></div>
}

function Profile({ initial, profileCode, authConfig, googleLinked, googleEmailRecorded, onGoogleSignIn, onSave }: { initial?: Student; profileCode?: string; authConfig: AuthConfig; googleLinked: boolean; googleEmailRecorded: boolean; onGoogleSignIn: (credential: string, displayName: string, student: Student) => Promise<void>; onSave: (value: Student, profileCode: string) => void }) {
  const [name, setName] = useState(initial?.name || '')
  const [semester, setSemester] = useState(initial?.semester || '1')
  const [focus, setFocus] = useState(initial?.focus || 'clinica')
  const [mode, setMode] = useState<'new' | 'recover'>('new')
  const [recoveryCode, setRecoveryCode] = useState('')
  const [createdCode, setCreatedCode] = useState('')
  const [error, setError] = useState('')
  const profileValue = () => ({ name: name.trim(), semester, focus })
  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault()
    if (name.trim().length < 2) { setError('Informe seu nome para criar seu perfil de jogador.'); return }
    if (profileCode) { onSave(profileValue(), profileCode); return }
    if (mode === 'recover') {
      const code = recoveryCode.trim().toUpperCase()
      if (!profileCodePattern.test(code)) { setError('Confira o código no formato MISSAO-XXXX-XXXX-XXXX.'); return }
      onSave(profileValue(), code)
      return
    }
    setError('')
    setCreatedCode(generateProfileCode())
  }
  if (createdCode) return <main className="profile-shell"><section className="profile-card identity-card"><div className="profile-mark">✦</div><span className="eyebrow">IDENTIDADE DA CENTRAL</span><h1>Guarde seu <em>código.</em></h1><p>Ele reúne suas próximas partidas, XP e recordes mesmo se você trocar de navegador ou dispositivo.</p><code className="profile-code">{createdCode}</code><small>Não é senha e não identifica você fora do jogo. Guarde-o para recuperar seu progresso.</small><button className="primary" onClick={() => onSave(profileValue(), createdCode)}>Guardei meu código →</button></section></main>
  const currentStudent = profileValue()
  return <main className="profile-shell"><section className="profile-card"><div className="profile-mark">✦</div><span className="eyebrow">MISSÃO IMUNIDADE · AMBIENTE DE APRENDIZAGEM</span><h1>{profileCode ? <>Seu perfil de <em>jogador.</em></> : <>Antes do primeiro <em>plantão.</em></>}</h1><p>{profileCode ? googleLinked ? 'Sua jornada já está conectada à sua conta Google e pode ser recuperada junto do seu código.' : 'Use seu código ou conecte o Google para levar a mesma jornada a outro dispositivo.' : 'Monte seu perfil de estudo e crie uma identidade recuperável.'}</p>{profileCode && <code className="profile-code compact-code">{profileCode}</code>}{!profileCode && <div className="identity-mode"><button type="button" className={mode === 'new' ? 'selected' : ''} onClick={() => { setMode('new'); setError('') }}>Criar código</button><button type="button" className={mode === 'recover' ? 'selected' : ''} onClick={() => { setMode('recover'); setError('') }}>Tenho um código</button></div>}<form onSubmit={submit}><label>Como devemos chamar você?<input value={name} onChange={(event) => setName(event.target.value)} placeholder="Seu nome" maxLength={60} /></label>{!profileCode && mode === 'recover' && <label>Seu código de jogador<input value={recoveryCode} onChange={(event) => setRecoveryCode(event.target.value.toUpperCase())} placeholder="MISSAO-ABCD-EFGH-IJKL" maxLength={21} autoCapitalize="characters" /></label>}<small>Seu nome aparece nos Recordes. Semestre e eixo de estudo ficam somente neste navegador.</small><div className="profile-row"><label>Semestre<select value={semester} onChange={(event) => setSemester(event.target.value)}>{Array.from({ length: 12 }, (_, i) => <option value={String(i + 1)} key={i}>{i + 1}º semestre</option>)}</select></label><label>Eixo de estudo<select value={focus} onChange={(event) => setFocus(event.target.value)}><option value="clinica">Raciocínio clínico</option><option value="microbiologia">Microbiologia</option><option value="epidemiologia">Epidemiologia</option><option value="saudeColetiva">Saúde coletiva</option></select></label></div>{error && <p className="form-error">{error}</p>}<button className="primary">{profileCode ? 'Salvar perfil' : mode === 'recover' ? 'Recuperar minha central →' : 'Criar meu código →'}</button></form><GoogleSignIn config={authConfig} linked={googleLinked} emailRecorded={googleEmailRecorded} onSignIn={(credential) => onGoogleSignIn(credential, name.trim(), currentStudent)} /></section></main> }


function EvolutionPanel({ player, onClose, onUpdate }: { player: Player; onClose: () => void; onUpdate: (update: Pick<Player, 'coins' | 'inventory' | 'equippedStyle'>) => void }) {
  const [message, setMessage] = useState('')
  const [busy, setBusy] = useState('')
  const level = Math.floor(player.xp / 700) + 1
  const owned = new Set(player.inventory)
  const useItem = async (path: string, itemId: string) => {
    setBusy(itemId); setMessage('')
    try {
      const response = await fetch(path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ playerId: player.playerId, itemId }) })
      const result = await response.json()
      if (!response.ok) throw new Error(result.error || 'Não foi possível atualizar a central.')
      onUpdate({ coins: result.coins, inventory: result.inventory, equippedStyle: result.equippedStyle })
      setMessage(result.message || 'Central atualizada.')
    } catch (error) { setMessage(error instanceof Error ? error.message : 'Não foi possível atualizar a central.') } finally { setBusy('') }
  }
  const achievements = [{ icon: '✦', title: 'Primeira resposta', note: 'Conclua um dossiê.', unlocked: player.completed.length >= 1 }, { icon: '◉', title: 'Equipe de campo', note: 'Conclua três dossiês.', unlocked: player.completed.length >= 3 }, { icon: '⚙', title: 'Investigador', note: 'Alcance o nível 3.', unlocked: level >= 3 }, { icon: '★', title: 'Campanha completa', note: 'Conclua todos os dossiês.', unlocked: player.completed.length >= missions.length }]
  const equipped = cosmeticById[player.equippedStyle] || cosmeticById.central
  return <div className="modal-backdrop" role="presentation"><section className="modal evolution-modal" role="dialog" aria-modal="true" aria-labelledby="evolution-title"><button className="modal-close" onClick={onClose} aria-label="Fechar central de evolução">×</button><span className="modal-kicker">CENTRAL DE EVOLUÇÃO</span><h2 id="evolution-title">Sua equipe está crescendo.</h2><p>XP reconhece sua trajetória. Moedas liberam itens visuais para sua central, sem alterar as escolhas clínicas.</p><section className="evolution-hero"><div className={`evolution-emblem avatar-${equipped.tone}`}>{equipped.icon}</div><div><span>NÍVEL {level} · {levelTitle(level)}</span><h3>{player.xp.toLocaleString('pt-BR')} XP acumulados</h3><p>Faltam {Math.max(0, level * 700 - player.xp)} XP para o próximo nível.</p></div><b>◉ {player.coins}</b></section><section className="achievement-grid">{achievements.map((item) => <article className={item.unlocked ? 'unlocked' : ''} key={item.title}><span>{item.icon}</span><div><b>{item.title}</b><small>{item.unlocked ? 'Conquistado' : item.note}</small></div></article>)}</section><section className="cosmetic-shop"><div><span className="eyebrow">ARMÁRIO DA CENTRAL</span><h3>Escolha seu emblema</h3></div><div className="cosmetic-grid">{cosmeticCatalog.map((item) => { const isOwned = owned.has(item.id); const isEquipped = player.equippedStyle === item.id; const levelReady = level >= item.level; return <article className={`cosmetic-card ${isEquipped ? 'equipped' : ''} ${!levelReady ? 'locked' : ''}`} key={item.id}><div className={`cosmetic-icon avatar-${item.tone}`}>{item.icon}</div><span>NÍVEL {item.level}</span><h4>{item.label}</h4><p>{item.description}</p>{isOwned ? <button className={isEquipped ? 'secondary' : 'primary'} disabled={isEquipped || busy === item.id} onClick={() => useItem('/api/rewards/equip', item.id)}>{isEquipped ? 'Em uso' : 'Equipar'}</button> : !levelReady ? <button className="secondary" disabled>Desbloqueia no nível {item.level}</button> : <button className="primary" disabled={player.coins < item.price || busy === item.id} onClick={() => useItem('/api/rewards/purchase', item.id)}>{player.coins < item.price ? `Faltam ${item.price - player.coins} moedas` : `Desbloquear · ${item.price} moedas`}</button>}</article> })}</div></section>{message && <p className="evolution-message" aria-live="polite">{message}</p>}</section></div>
}

function RecordsPanel({ records, error, onClose, onRetry }: { records: Records | null; error: string; onClose: () => void; onRetry: () => void }) {
  const [showParticipants, setShowParticipants] = useState(false)
  const label = (entry: RecordEntry | Participant) => entry.displayName?.trim() || 'Jogador'
  const board = (title: string, entries: RecordEntry[], suffix: string) => <section className="records-board"><h3>{title}</h3>{entries.length ? <ol>{entries.map((entry, index) => <li key={`${title}-${entry.displayName}-${index}`}><span>{index + 1}</span><b>{label(entry)}</b><em>{entry.value.toLocaleString('pt-BR')} {suffix}</em></li>)}</ol> : <p>Ainda não há uma marca registrada.</p>}</section>
  const date = (value: string | null) => value ? new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: 'short' }).format(new Date(value)) : 'ainda não jogou'
  return <div className="modal-backdrop" role="presentation"><section className="modal records-modal" role="dialog" aria-modal="true" aria-label="Recordes da central"><button className="modal-close" onClick={onClose} aria-label="Fechar recordes">×</button><span className="modal-kicker">CENTRAL EM MOVIMENTO</span><h2>Recordes da equipe</h2>{error ? <><p>{error}</p><div className="modal-actions"><button className="primary" onClick={onRetry}>Tentar novamente</button></div></> : !records ? <p>Carregando os dados da central…</p> : <><div className="records-summary"><span><b>{records.summary.players}</b> {records.summary.players === 1 ? 'jogador' : 'jogadores'}</span><span><b>{records.summary.active_players}</b> ativos no mês</span><span><b>{records.summary.plays}</b> partidas</span><span><b>{records.summary.completed}</b> dossiês concluídos</span></div><p className="records-note">O ranking mostra o nome de exibição escolhido pelo estudante. Ele não guarda e-mail, senha, semestre ou eixo de estudo.</p><div className="records-grid">{board('Melhor pontuação', records.leaderboards.score, 'pts')}{board('Mais experiência', records.leaderboards.xp, 'XP')}{board('Mais partidas', records.leaderboards.plays, 'partidas')}</div><section className="participants-section"><div><span className="eyebrow">ACOMPANHAMENTO</span><h3>Quem está testando?</h3><p>Lista dos 30 jogadores com mais XP. Cada código de jogador consolida todas as suas partidas.</p></div><button className="secondary" onClick={() => setShowParticipants((value) => !value)}>{showParticipants ? 'Ocultar lista' : `+ Ver ${Math.min(30, records.participants.length)} jogadores`}</button>{showParticipants && <div className="participants-list">{records.participants.map((participant, index) => <article key={`${participant.displayName}-${participant.createdAt}-${index}`}><b>{index + 1}</b><div><strong>{label(participant)}</strong><small>Entrou em {date(participant.createdAt)} · última partida: {date(participant.lastPlayedAt)}</small></div><span><em>{participant.xp.toLocaleString('pt-BR')} XP</em><small>{participant.plays} partida{participant.plays === 1 ? '' : 's'} · {participant.completed} caso{participant.completed === 1 ? '' : 's'}</small></span></article>)}</div>}</section></>}</section></div>
}

function JourneyPanel({ journey, error, onClose, onRetry }: { journey: Journey | null; error: string; onClose: () => void; onRetry: () => void }) {
  const missionName = (id: number) => missions.find((mission) => mission.id === id)?.shortName || `Dossiê ${id}`
  const date = (value: string) => new Intl.DateTimeFormat('pt-BR', { day: '2-digit', month: 'short' }).format(new Date(value))
  return <div className="modal-backdrop" role="presentation"><section className="modal journey-modal" role="dialog" aria-modal="true" aria-label="Sua jornada"><button className="modal-close" onClick={onClose} aria-label="Fechar jornada">×</button><span className="modal-kicker">DIÁRIO PESSOAL DA CENTRAL</span><h2>Sua jornada de investigação</h2>{error ? <><p>{error}</p><button className="primary" onClick={onRetry}>Tentar novamente</button></> : !journey ? <p>Carregando sua trajetória…</p> : <><p className="journey-intro">Cada conclusão registra o caminho da equipe. Seu histórico fica ligado ao seu código de jogador ou, se escolher, à conta Google conectada.</p><section className="journey-summary"><article><b>{journey.summary.total_runs}</b><span>partidas registradas</span></article><article><b>{journey.summary.wins}</b><span>casos concluídos</span></article><article><b>{journey.summary.average_score.toLocaleString('pt-BR')}</b><span>pontuação média</span></article><article><b>{journey.profile?.streak || 0}</b><span>dias de sequência</span></article></section><section className="journey-history"><div><span className="eyebrow">ÚLTIMOS PERCURSOS</span><h3>O que sua equipe viveu</h3></div>{journey.runs.length ? journey.runs.map((run) => <article className={run.outcome === 'won' ? 'won' : 'lost'} key={`${run.missionId}-${run.createdAt}`}><span>{run.outcome === 'won' ? '✓' : '!'}</span><div><b>{missionName(run.missionId)}</b><small>{date(run.createdAt)} · ciclo {run.cycle} · {run.cases} casos acompanhados</small></div><em>{run.outcome === 'won' ? `+${run.xpEarned} XP` : 'rota revisada'}</em></article>) : <p>Nenhuma partida concluída foi registrada ainda. Termine um dossiê para iniciar seu diário.</p>}</section></>}</section></div>
}

function AdminPanel({ config, onAuthenticated, onClose }: { config: AuthConfig; onAuthenticated: () => void; onClose: () => void }) {
  const mount = useRef<HTMLDivElement>(null)
  const [authenticated, setAuthenticated] = useState(false)
  const [data, setData] = useState<AdminData | null>(null)
  const [message, setMessage] = useState('Verificando acesso…')
  const loadStats = () => fetch('/api/admin/stats', { cache: 'no-store' }).then(async (response) => { if (!response.ok) throw new Error('A sessão administrativa não está ativa.'); return response.json() as Promise<AdminData> }).then((value) => { setData(value); setAuthenticated(true); onAuthenticated(); setMessage('') })
  useEffect(() => { void fetch('/api/admin/session', { cache: 'no-store' }).then((response) => response.json()).then((session: { authenticated?: boolean }) => { if (session.authenticated) return loadStats(); setAuthenticated(false); setMessage('Entre com a conta Google autorizada para abrir o painel.') }).catch(() => setMessage('Não foi possível verificar o acesso administrativo.')) }, [])
  useEffect(() => {
    if (authenticated || !config.googleClientId || !mount.current) return
    let cancelled = false
    const render = () => {
      if (cancelled || !mount.current || !window.google) return
      mount.current.replaceChildren()
      window.google.accounts.id.initialize({ client_id: config.googleClientId!, callback: (result) => { if (!result.credential) return; setMessage('Validando acesso…'); void fetch('/api/admin/google', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ credential: result.credential }) }).then(async (response) => { const body = await response.json().catch(() => null) as { error?: string } | null; if (!response.ok) throw new Error(body?.error || 'Acesso negado.'); return loadStats() }).catch((error: unknown) => setMessage(error instanceof Error ? error.message : 'Acesso negado.')) } })
      window.google.accounts.id.renderButton(mount.current, { theme: 'outline', size: 'large', width: 290, text: 'continue_with', shape: 'pill', locale: 'pt-BR' })
    }
    const script = document.querySelector<HTMLScriptElement>('script[data-missao-google]')
    if (script) { if (window.google) render(); else script.addEventListener('load', render, { once: true }) } else { const created = document.createElement('script'); created.src = 'https://accounts.google.com/gsi/client'; created.async = true; created.defer = true; created.dataset.missaoGoogle = 'true'; created.addEventListener('load', render, { once: true }); document.head.appendChild(created) }
    return () => { cancelled = true }
  }, [authenticated, config.googleClientId])
  const date = (value: string | null) => value ? new Intl.DateTimeFormat('pt-BR', { dateStyle: 'short', timeStyle: 'short' }).format(new Date(value)) : 'sem partida'
  return <div className="modal-backdrop"><section className="modal admin-modal" role="dialog" aria-modal="true" aria-label="Painel administrativo"><button className="modal-close" onClick={onClose} aria-label="Fechar painel">×</button><span className="modal-kicker">ACESSO RESTRITO</span><h2>Painel administrativo</h2>{!data ? <><p>{message}</p><div ref={mount} className="admin-google" /></> : <><p className="records-note">Acesso: {data.admin}. Os e-mails abaixo foram fornecidos mediante autorização no vínculo Google.</p><div className="admin-overview"><article><b>{data.overview.visits}</b><span>visitas registradas</span></article><article><b>{data.overview.visits_24h}</b><span>nas últimas 24 h</span></article><article><b>{data.overview.active_30d}</b><span>jogadores ativos em 30 dias</span></article><article><b>{data.overview.google_links}</b><span>vínculos Google</span></article><article><b>{data.overview.runs}</b><span>partidas encerradas</span></article></div><section className="admin-missions"><h3>Uso por missão</h3>{data.missions.map((mission) => <span key={mission.missionId}><b>{missions.find((item) => item.id === mission.missionId)?.shortName || `Dossiê ${mission.missionId}`}</b>{mission.runs} partidas · {mission.wins} conclusões · média {mission.averageScore || 0}</span>)}</section><section className="admin-funnel"><div className="admin-section-heading"><span className="eyebrow">FUNIL DE JOGABILIDADE</span><h3>Onde as missões prendem ou perdem jogadores</h3><p>Abandono é uma estimativa: inclui partidas ainda em andamento.</p></div><div className="admin-funnel-grid">{data.funnel?.map((item) => { const completion = item.starts ? Math.round(item.finishes / item.starts * 100) : 0; const abandoned = Math.max(0, item.starts - item.finishes); return <article key={item.missionId}><div><b>{missions.find((mission) => mission.id === item.missionId)?.shortName || `Dossiê ${item.missionId}`}</b><strong>{completion}%</strong></div><span><i style={{ width: `${completion}%` }} /></span><small>{item.starts} iniciadas · {item.finishes} concluídas · {abandoned} em aberto</small><em>{item.hintRuns} usaram dicas · {item.diagnosisRuns} chegaram ao diagnóstico</em></article> })}</div></section><section className="admin-players"><h3>Jogadores e atividade</h3><div className="admin-table"><div className="admin-row admin-head"><b>Jogador</b><b>E-mail vinculado</b><b>Atividade</b><b>Progresso</b></div>{data.players.map((item, index) => <div className="admin-row" key={`${item.email || item.displayName}-${index}`}><span><b>{item.displayName || 'Sem nome'}</b><small>{item.visits} visita{item.visits === 1 ? '' : 's'}</small></span><span>{item.email || 'Sem Google'}</span><span><b>{item.plays} partida{item.plays === 1 ? '' : 's'}</b><small>{date(item.lastPlayedAt)}</small></span><span><b>{item.xp} XP</b><small>{item.completed} dossiês · recorde {item.bestScore}</small></span></div>)}</div></section></>}</section></div>
}

function CampaignMap({ student, player, completed, testMode, tutorial, googleLinked, adminEnabled, onTutorial, onCloseTutorial, onEdit, onStart, onRecords, onEvolution, onJourney, onAdmin }: { student: Student; player: Player; completed: number[]; testMode: boolean; tutorial: boolean; googleLinked: boolean; adminEnabled: boolean; onTutorial: () => void; onCloseTutorial: () => void; onEdit: () => void; onStart: (mission: Mission, isDaily?: boolean) => void; onRecords: () => void; onEvolution: () => void; onJourney: () => void; onAdmin: () => void }) {
  const [selected, setSelected] = useState(missions[0])
  const first = student.name.split(' ')[0]
  const today = localDay()
  const chapterOneComplete = missions.filter((item) => item.id <= 8).every((item) => completed.includes(item.id))
  const isUnlocked = (item: Mission) => {
    if (testMode || item.id === 1) return true
    if (item.id <= 8) return completed.includes(item.id - 1)
    if (!chapterOneComplete) return false
    const route = chapterTwoRoutes.find((entry) => entry.missionIds.includes(item.id))
    if (!route) return false
    const position = route.missionIds.indexOf(item.id)
    return position === 0 || completed.includes(route.missionIds[position - 1])
  }
  const dispatchPool = dailyDispatches.filter((item) => isUnlocked(missions.find((mission) => mission.id === item.missionId) || missions[0]))
  const dispatch = dispatchPool[Number(today.split('-').join('')) % dispatchPool.length]
  const dailyMission = missions.find((item) => item.id === dispatch.missionId) || missions[0]
  const claimed = player.dailyClaimed === today
  const selectedDone = completed.includes(selected.id)
  useEffect(() => {
    const account = document.querySelector('.map-base-shell .campaign-account')
    if (!account || account.querySelector('[data-journey-trigger]')) return
    const button = document.createElement('button')
    button.className = 'journey-button'; button.type = 'button'; button.textContent = 'Jornada'; button.dataset.journeyTrigger = 'true'
    button.addEventListener('click', onJourney)
    const records = account.querySelector('.records-button')
    account.insertBefore(button, records || null)
    const admin = adminEnabled ? document.createElement('button') : null
    if (admin) { admin.className = 'admin-button'; admin.type = 'button'; admin.textContent = 'Admin'; admin.dataset.adminTrigger = 'true'; admin.addEventListener('click', onAdmin); account.insertBefore(admin, records || null) }
    return () => { button.removeEventListener('click', onJourney); button.remove(); if (admin) { admin.removeEventListener('click', onAdmin); admin.remove() } }
  }, [onJourney, onAdmin, adminEnabled])
  return <main className="campaign-shell map-base-shell"><header className="campaign-header"><div className="brand"><span className="brand-mark">✦</span><span>MISSÃO <b>IMUNIDADE</b></span></div><div className="campaign-account"><PlayerHud player={player} /><button className="evolution-button" onClick={onEvolution}>Central</button><button className="records-button" onClick={onRecords}>🏆 Recordes</button><button className="help-button" onClick={onTutorial}>Como jogar</button><button className="profile-account-button" onClick={onEdit}>{first} · {student.semester}º semestre{googleLinked && <span className="google-linked-badge">✓ Google</span>}</button></div></header><section className="map-base-heading"><span className="eyebrow">CENTRAL DE OPERAÇÕES · CENÁRIOS SIMULADOS</span><h1>Olá, {first}. Onde a equipe atua agora?</h1><p>Toque em um foco no mapa. Cada marcador guarda um caso, seu estado e a próxima ação.</p></section><section className="mission-world"><img src={worldMapImage} alt="Mapa-múndi com focos de missão" />{missions.map((item, index) => { const unlocked = isUnlocked(item); const done = completed.includes(item.id); return <button aria-label={`${item.shortName}, ${done ? 'território controlado' : unlocked ? 'alerta disponível' : 'bloqueado'}`} className={`world-mission-pin ${selected.id === item.id ? 'selected' : ''} ${done ? 'controlled' : ''} ${!unlocked ? 'locked' : ''}`} disabled={!unlocked} key={item.id} style={{ left: `${item.mapPosition.x}%`, top: `${item.mapPosition.y}%` }} onClick={() => setSelected(item)}><i>{done ? '✓' : index + 1}</i><span>{done ? 'Controlado' : 'Alerta'}</span></button> })}<button className={`daily-beacon ${claimed ? 'claimed' : ''}`} onClick={() => { setSelected(dailyMission); document.getElementById('mission-sheet')?.scrollIntoView({ behavior: 'smooth', block: 'nearest' }) }}><b>✦ Missão diária</b><small>{claimed ? 'resgatada' : '+80 XP · +15 moedas'}</small></button></section><section id="mission-sheet" className={`mission-sheet ${selectedDone ? 'controlled' : ''}`}><div className="sheet-status"><span>{selectedDone ? '✓ TERRITÓRIO CONTROLADO' : '● ALERTA ATIVO'}</span><b>{selected.caseCode.toUpperCase()}</b></div><div className="sheet-copy"><span>{selected.region} · {selected.location}</span><h2>{selected.shortName}</h2><p>{selected.openingSyndrome}</p><small>Um cenário educativo inspirado em contextos epidemiológicos reais.</small></div><div className="sheet-actions"><button className="pilot-primary" disabled={!isUnlocked(selected)} onClick={() => onStart(selected)}>{selectedDone ? 'Reabrir dossiê' : 'Assumir operação'} <span>→</span></button><button className="sheet-daily" onClick={() => onStart(dailyMission, !claimed)}>{claimed ? 'Ver alerta diária' : 'Aceitar missão diária'} </button></div></section><section className="map-progress"><div><b>{completed.length}/{missions.length}</b><span>territórios acompanhados</span></div><div><b>{player.streak}</b><span>dia{player.streak === 1 ? '' : 's'} de sequência</span></div><div><b>{player.xp}</b><span>XP da equipe</span></div></section>{tutorial && <Tutorial onClose={onCloseTutorial} />}</main>
}

function CampaignChapter({ completed, testMode, onStart }: { completed: number[]; testMode: boolean; onStart: (mission: Mission) => void }) {
  const chapterOne = missions.filter((mission) => mission.id <= 8)
  const chapterTwo = missions.filter((mission) => mission.id > 8)
  const chapterOneDone = chapterOne.filter((mission) => completed.includes(mission.id)).length
  const chapterTwoDone = chapterTwo.filter((mission) => completed.includes(mission.id)).length
  const chapterOpen = chapterOneDone >= chapterOne.length
  const chapterAvailable = chapterOpen || testMode
  const remaining = Math.max(0, chapterOne.length - chapterOneDone)
  const [selectedRoute, setSelectedRoute] = useState(chapterTwoRoutes[0].id)
  const activeRoute = chapterTwoRoutes.find((route) => route.id === selectedRoute) || chapterTwoRoutes[0]
  const routeMissions = activeRoute.missionIds.map((id) => missions.find((mission) => mission.id === id)).filter((mission): mission is Mission => Boolean(mission))
  const routeDone = (route: typeof chapterTwoRoutes[number]) => route.missionIds.filter((id) => completed.includes(id)).length
  const routeUnlocked = (route: typeof chapterTwoRoutes[number], missionId: number) => {
    if (!chapterAvailable) return false
    const position = route.missionIds.indexOf(missionId)
    return position === 0 || completed.includes(route.missionIds[position - 1])
  }
  return <><section className={`campaign-chapter ${chapterOpen ? 'complete' : ''}`} aria-label="Progresso do capítulo"><div className="chapter-orbit"><i>✦</i><i>✦</i><i>✦</i></div><div><span>CAPÍTULO 1 · FUNDAMENTOS DA RESPOSTA</span><h2>{chapterOpen ? 'Todos os territórios do capítulo estão controlados.' : `${chapterOneDone} de ${chapterOne.length} territórios protegidos.`}</h2><p>{chapterOpen ? 'A Central reconhece a campanha concluída. Quatro rotas de especialização foram abertas.' : `Faltam ${remaining} dossiê${remaining === 1 ? '' : 's'} para desbloquear a cerimônia de fechamento do capítulo.`}</p></div><div className="chapter-seals" aria-label={`${chapterOneDone} selos conquistados`}>{chapterOne.map((mission) => <i className={completed.includes(mission.id) ? 'earned' : ''} key={mission.id}>{completed.includes(mission.id) ? '✓' : mission.id}</i>)}</div></section>{chapterOpen && <section className="chapter-finale" aria-label="Cerimonia de conclusão do capítulo"><div className="finale-sky" /><div className="finale-signal">✦</div><div><span>TRANSMISSÃO DA CENTRAL · CAPITULO CONCLUÍDO</span><h2>O mapa respondeu a sua equipe.</h2><p>Oito territórios saíram do alerta para o controle. Agora você escolhe uma rota e desenvolve competências diferentes.</p></div><div className="finale-reward"><b>SELO CONQUISTADO</b><strong>Guardião da Resposta</strong><small>Quatro rotas disponíveis</small></div></section>}<section className={`chapter-two-preview route-command ${chapterAvailable ? 'ready' : ''}`} aria-label="Capitulo 2"><header><span>CAPÍTULO 2 · ROTAS DE ESPECIALIZAÇÃO</span><h2>{chapterAvailable ? `${chapterTwoDone} de ${chapterTwo.length} operações controladas.` : 'Sinais distantes no radar.'}</h2><p>{chapterAvailable ? 'Escolha um caminho. Cada rota muda o tipo de problema que sua equipe precisa resolver.' : 'Conclua o primeiro capítulo para liberar quatro caminhos de investigação.'}</p></header><nav className="route-selector" aria-label="Escolha uma rota">{chapterTwoRoutes.map((route) => { const done = routeDone(route); const complete = done === route.missionIds.length; return <button key={route.id} className={`${route.color} ${selectedRoute === route.id ? 'active' : ''} ${complete ? 'complete' : ''}`} onClick={() => setSelectedRoute(route.id)}><i>{complete ? '✓' : route.icon}</i><span><b>{route.title}</b><small>{done}/{route.missionIds.length} operações</small></span></button> })}</nav><section className={`route-brief route-${activeRoute.color}`}><div className="route-signal"><i>{activeRoute.icon}</i><span>ROTA SELECIONADA</span></div><div><h3>{activeRoute.title}</h3><p>{activeRoute.subtitle}</p></div><div className={`route-seal ${routeDone(activeRoute) === activeRoute.missionIds.length ? 'earned' : ''}`}><small>{routeDone(activeRoute) === activeRoute.missionIds.length ? 'SELO CONQUISTADO' : 'SELO DA ROTA'}</small><b>{activeRoute.seal}</b></div></section><div className="route-mission-line">{routeMissions.map((mission, index) => { const done = completed.includes(mission.id); const unlocked = routeUnlocked(activeRoute, mission.id); return <article className={`${done ? 'controlled' : ''} ${!unlocked ? 'locked' : ''}`} key={mission.id}><span className="draft-number">{String(mission.id).padStart(2, '0')}</span><b>{done ? 'TERRITÓRIO CONTROLADO' : unlocked ? `ETAPA ${index + 1} DISPONÍVEL` : 'AGUARDA A ETAPA ANTERIOR'}</b><h3>{mission.shortName}</h3><p>{mission.brief}</p><dl><div><dt>Desafio da rota</dt><dd>{mission.openingSyndrome}</dd></div><div><dt>Progresso</dt><dd>{done ? 'Caso registrado no diário da equipe.' : unlocked ? 'Sua equipe pode assumir esta operação agora.' : 'Conclua a operação anterior desta rota.'}</dd></div></dl><footer><span>{mission.region} · {mission.location}</span><button disabled={!unlocked} onClick={() => onStart(mission)}>{done ? 'Reabrir operação' : unlocked ? 'Assumir operação' : 'Bloqueada'} <b>→</b></button></footer></article> })}</div></section></>
}

function Campaign({ student, player, completed, testMode, tutorial, onTutorial, onCloseTutorial, onEdit, onStart, onRecords, onEvolution }: { student: Student; player: Player; completed: number[]; testMode: boolean; tutorial: boolean; onTutorial: () => void; onCloseTutorial: () => void; onEdit: () => void; onStart: (mission: Mission, isDaily?: boolean) => void; onRecords: () => void; onEvolution: () => void }) { const [mapMission, setMapMission] = useState(missions[0]); const first = student.name.split(' ')[0]; const today = localDay(); const dispatch = dailyDispatches[Number(today.split('-').join('')) % dailyDispatches.length]; const dailyMission = missions.find((mission) => mission.id === dispatch.missionId) || missions[0]; const claimed = player.dailyClaimed === today; return <main className="campaign-shell"><header className="campaign-header"><div className="brand"><span className="brand-mark">✦</span><span>MISSÃO <b>IMUNIDADE</b></span></div><div className="campaign-account"><PlayerHud player={player} /><button className="evolution-button" onClick={onEvolution}>Central</button><button className="records-button" onClick={onRecords}>🏆 Recordes</button><button className="help-button" onClick={onTutorial}>Como jogar</button><button onClick={onEdit}>{first} · {student.semester}º semestre</button></div></header><section className="campaign-hero"><img src={worldMapImage} alt="Mapa-múndi ilustrativo" /><div className="campaign-map-focus" style={{ left: `${mapMission.mapPosition.x}%`, top: `${mapMission.mapPosition.y}%` }}><i /><span><b>{mapMission.caseCode} · {mapMission.shortName}</b>{mapMission.location}</span></div><div className="campaign-hero-copy"><span className="eyebrow">CENTRAL DE INVESTIGAÇÃO</span><h1>Olá, {first}.<br />Vamos ler o <em>surto.</em></h1><p>Assuma um dossiê, coordene a equipe e transforme evidência em resposta.</p><div className="campaign-progress"><b>{completed.length}/{missions.length}</b><span>missões concluídas · foco: {focusLabels[student.focus]}</span></div></div></section><section className={`daily-dispatch ${claimed ? 'claimed' : ''}`}><div className="daily-orbit">✦</div><div><span>{dispatch.label} · MISSÃO DO DIA</span><h2>{dispatch.title}</h2><p>{dispatch.text}</p><b>Objetivo: {dispatch.objective}</b></div><div className="daily-reward"><span>{claimed ? 'RESGATADO HOJE' : 'RECOMPENSA DIÁRIA'}</span><strong>{claimed ? '✓ concluída' : '+80 XP · +15 moedas'}</strong><small>Sequência atual: {player.streak} dia{player.streak === 1 ? '' : 's'} 🔥</small><button onClick={() => onStart(dailyMission, !claimed)}>{claimed ? 'Revisar missão' : 'Aceitar alerta'} <b>→</b></button></div></section><section><div className="campaign-title"><div><span className="eyebrow">DOSSIÊS DISPONÍVEIS</span><h2>Onde sua equipe atua agora?</h2></div><p>Toque ou use Tab para localizar o dossiê no mapa e depois assumir o caso.</p></div><div className="mission-grid">{missions.map((mission, index) => { const unlocked = testMode || index === 0 || completed.includes(missions[index - 1].id); const done = completed.includes(mission.id); return <article className={`mission-card ${!unlocked ? 'locked' : ''} ${done ? 'done' : ''} ${mapMission.id === mission.id ? 'map-active' : ''}`} key={mission.id} onMouseEnter={() => setMapMission(mission)} onFocus={() => setMapMission(mission)} onClick={() => setMapMission(mission)}><span className="mission-number">{done ? '✓' : `0${mission.id}`}</span><div className="mission-card-icon">{['🌊', '🦟', '🧭', '🏥', '🧫'][index] || '✦'}</div><span>{mission.region}</span><h3>{mission.shortName}</h3><p>{mission.openingSyndrome}</p><button disabled={!unlocked} onClick={(event) => { event.stopPropagation(); onStart(mission) }}>{unlocked ? (done ? 'Reabrir dossiê' : 'Assumir caso') : 'Dossiê bloqueado'} <b>→</b></button></article> })}</div></section>{tutorial && <Tutorial onClose={onCloseTutorial} />}</main> }

function Tutorial({ onClose }: { onClose: () => void }) { return <div className="modal-backdrop tutorial-backdrop"><section className="tutorial tutorial-complete" role="dialog" aria-modal="true" aria-labelledby="tutorial-title"><span className="modal-kicker">GUIA RÁPIDO · COMO JOGAR</span><h2 id="tutorial-title">Comande uma resposta, não um questionário.</h2><p>Você toma decisões em uma central de resposta. A meta é proteger pessoas e explicar por que uma hipótese orienta o plano.</p><div className="tutorial-steps tutorial-short"><article><b>1</b><div><h3>Leia o chamado</h3><p>Veja o cenário e os indicadores. Casos, atendimento, prazo e recursos contam histórias diferentes.</p></div></article><article><b>2</b><div><h3>Acione a equipe</h3><p>Cada personagem entrega uma lente. Exames custam recursos e podem chegar no próximo ciclo.</p></div></article><article><b>3</b><div><h3>Cuide e investigue</h3><p>Uma urgência pode pedir ação antes da confirmação. Depois, conecte clínica, exposição, vigilância e laboratório.</p></div></article><article><b>4</b><div><h3>Revise sua partida</h3><p>O debriefing mostra o que suas próprias decisões revelam sobre investigação, conduta e controle.</p></div></article></div><div className="tutorial-tip"><b>Dica:</b> informações isoladas raramente bastam. Use mais de uma lente antes de defender uma hipótese.</div><div className="modal-actions"><button className="primary" onClick={onClose}>Entrar na central</button></div></section></div> }

createRoot(document.getElementById('root')!).render(<App />)
